import os
from typing import Any, BinaryIO, Dict, List, Optional, Union

from azure.core.credentials import AzureKeyCredential
from azure.ai.documentintelligence import DocumentIntelligenceClient


def extract_tables_and_rows(
    document: Union[str, bytes, BinaryIO],
    *,
    content_type: str = "application/octet-stream",
    model_id: str = "prebuilt-layout",
    endpoint: Optional[str] = None,
    api_key: Optional[str] = None,
) -> Dict[str, Any]:
    endpoint = endpoint or os.environ["AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT"]
    api_key = api_key or os.environ["AZURE_DOCUMENT_INTELLIGENCE_KEY"]

    client = DocumentIntelligenceClient(
        endpoint=endpoint,
        credential=AzureKeyCredential(api_key),
    )

    body: bytes
    if isinstance(document, bytes):
        body = document
    elif isinstance(document, str):
        with open(document, "rb") as f:
            body = f.read()
    else:
        body = document.read()

    poller = client.begin_analyze_document(
        model_id=model_id,
        body=body,
        content_type=content_type,
    )
    result = poller.result()

    pages_out: List[Dict[str, Any]] = []
    page_map: Dict[int, Dict[str, Any]] = {}

    for page in getattr(result, "pages", []) or []:
        page_info = {
            "page_number": getattr(page, "page_number", None),
            "width": getattr(page, "width", None),
            "height": getattr(page, "height", None),
            "unit": getattr(page, "unit", None),
            "tables": [],
        }
        pages_out.append(page_info)
        if page_info["page_number"] is not None:
            page_map[page_info["page_number"]] = page_info

    tables_out: List[Dict[str, Any]] = []
    for table_index, table in enumerate(getattr(result, "tables", []) or []):
        cells = []
        rows: Dict[int, List[Dict[str, Any]]] = {}

        bounding_regions = []
        page_numbers = set()
        for br in getattr(table, "bounding_regions", []) or []:
            region = {
                "page_number": getattr(br, "page_number", None),
                "polygon": getattr(br, "polygon", None),
            }
            bounding_regions.append(region)
            if region["page_number"] is not None:
                page_numbers.add(region["page_number"])

        for cell in getattr(table, "cells", []) or []:
            cell_regions = []
            for br in getattr(cell, "bounding_regions", []) or []:
                cell_regions.append(
                    {
                        "page_number": getattr(br, "page_number", None),
                        "polygon": getattr(br, "polygon", None),
                    }
                )

            cell_obj = {
                "row_index": getattr(cell, "row_index", None),
                "column_index": getattr(cell, "column_index", None),
                "row_span": getattr(cell, "row_span", 1),
                "column_span": getattr(cell, "column_span", 1),
                "kind": getattr(cell, "kind", None),
                "content": getattr(cell, "content", ""),
                "bounding_regions": cell_regions,
                "spans": [
                    {
                        "offset": getattr(span, "offset", None),
                        "length": getattr(span, "length", None),
                    }
                    for span in (getattr(cell, "spans", []) or [])
                ],
            }
            cells.append(cell_obj)

            row_idx = cell_obj["row_index"]
            if row_idx is not None:
                rows.setdefault(row_idx, []).append(cell_obj)

        row_list = []
        for row_index in sorted(rows.keys()):
            ordered_cells = sorted(
                rows[row_index],
                key=lambda c: (
                    c["column_index"] if c["column_index"] is not None else 10**9,
                    c["content"],
                ),
            )
            row_list.append(
                {
                    "row_index": row_index,
                    "cells": ordered_cells,
                    "text": " | ".join(c["content"] for c in ordered_cells if c["content"]),
                }
            )

        table_obj = {
            "table_index": table_index,
            "row_count": getattr(table, "row_count", None),
            "column_count": getattr(table, "column_count", None),
            "bounding_regions": bounding_regions,
            "cells": sorted(
                cells,
                key=lambda c: (
                    c["row_index"] if c["row_index"] is not None else 10**9,
                    c["column_index"] if c["column_index"] is not None else 10**9,
                ),
            ),
            "rows": row_list,
            "page_numbers": sorted(page_numbers),
        }
        tables_out.append(table_obj)

        for pn in page_numbers:
            if pn in page_map:
                page_map[pn]["tables"].append(table_obj)

    return {
        "model_id": model_id,
        "content_format": getattr(result, "content_format", None),
        "content": getattr(result, "content", None),
        "pages": pages_out,
        "tables": tables_out,
    }
